        self,
        subquery: Any,
        subquery_raw: str,
        alias: str | None,
        position: SourcePosition,
        generator: Column | None,
        column_names: list[str],
    ):
        """
        :param generator: the table generating function, like explode(tab.col1), as a column. None if not parsed
        :param column_names: column aliases of the lateral view, empty when the SQL does not specify them
