import itertools
from collections.abc import Mapping, Sequence
from typing import Any

from sqllineage.core.graph_operator import GraphOperator
from sqllineage.core.models import Column, Table, TableKeys


def list_lineage_paths_between(
    graph: GraphOperator, sources: set[Any], targets: set[Any]
) -> list[list[Any]]:
    """Naive path enumeration: every source/target pair, no filtering."""
    return [
        path
        for source, target in itertools.product(sources, targets)
        for path in graph.list_lineage_paths(source, target)
    ]


def cone_lineage_paths(
    graph: GraphOperator, seed: Any, sources: set[Any], targets: set[Any]
) -> list[list[Any]]:
    """
    Path enumeration restricted to the subgraph around ``seed``: only
    ancestors/descendants of ``seed`` are considered, so path enumeration
    runs on a much smaller subgraph than the full lineage graph.
    """
    ancestors = graph.ancestors(seed)
    descendants = graph.descendants(seed)
    true_sources = ancestors & sources
    true_targets = descendants & targets
    if seed in sources:
        true_sources.add(seed)
    if seed in targets:
        true_targets.add(seed)
    if not true_sources or not true_targets:
        return []

    cone_graph = graph.get_sub_graph(*(ancestors | descendants | {seed}))

    # seed reaching itself directly (a real self-loop edge) is a complete path
    # on its own, not a "half" to be stitched together with anything else.
    self_paths = (
        cone_graph.list_lineage_paths(seed, seed)
        if seed in true_sources and seed in true_targets
        else []
    )

    # Enumerating source-to-target paths directly over cone_graph would make
    # all_simple_paths explore every source/target pair's full route through
    # seed at once, an exponential blow-up in the number of routes on either
    # side. Splitting at seed and enumerating each half separately, then
    # stitching the halves together, keeps each all_simple_paths call scoped
    # to one side of the cone.
    up_paths = [[seed]] if seed in true_sources else []
    up_paths += list_lineage_paths_between(cone_graph, true_sources - {seed}, {seed})
    down_paths = [[seed]] if seed in true_targets else []
    down_paths += list_lineage_paths_between(cone_graph, {seed}, true_targets - {seed})
    joined = [
        up + down[1:]
        for up in up_paths
        for down in down_paths
        # the [seed] x [seed] pairing is the same relationship self_paths
        # already represents (correctly, as a self-loop edge or not at all);
        # skip it here so it isn't double-counted or wrongly trivialized.
        if not (up == [seed] and down == [seed])
        # a cycle through seed longer than a self-loop can put the same
        # vertex on both the ancestor and descendant side (e.g. seed -> x ->
        # seed); stitching such an up/down pair together would repeat that
        # vertex, so only join halves that share nothing but seed itself.
        and set(up[:-1]).isdisjoint(down[1:])
    ]
    return self_paths + joined


def _table_key_data(
    node: Any, table_keys: Mapping[Table, TableKeys] | None
) -> dict[str, Any]:
    if table_keys and isinstance(node, Table) and (keys := table_keys.get(node)):
        return {
            "primary_key": list(keys.primary_key),
            "foreign_keys": [
                {
                    "columns": list(fk.columns),
                    "referred_table": str(fk.referred_table),
                    "referred_columns": list(fk.referred_columns),
                }
                for fk in keys.foreign_keys
            ],
        }
    return {}


def _column_key_data(
    node: Any, table_keys: Mapping[Table, TableKeys] | None
) -> dict[str, Any]:
    if (
        table_keys
        and isinstance(node, Column)
        and isinstance(node.parent, Table)
        and (keys := table_keys.get(node.parent))
    ):
        col_keys: list[str] = []
        if node.raw_name in keys.primary_key:
            col_keys.append("PK")
        if any(node.raw_name in fk.columns for fk in keys.foreign_keys):
            col_keys.append("FK")
        if col_keys:
            return {"keys": col_keys}
    return {}


def build_cytoscape(
    vertices: Sequence[Any],
    edges: Sequence[tuple[Any, Any]],
    compound: bool = False,
    table_keys: Mapping[Table, TableKeys] | None = None,
) -> list[dict[str, dict[str, Any]]]:
    nodes: list[dict[str, dict[str, Any]]]
    if compound:
        parents_dict: dict[Any, dict[str, str]] = {}
        for node in vertices:
            parent = getattr(node, "parent", None)
            parents_dict[parent] = {
                "name": str(parent) if parent is not None else "<unknown>",
                "type": (
                    type(parent).__name__ if parent is not None else "Table or SubQuery"
                ),
            }
        nodes = []
        for node in vertices:
            parent = getattr(node, "parent", None)
            parent_candidates = getattr(node, "parent_candidates", [])
            nodes.append(
                {
                    "data": {
                        "id": str(node),
                        "parent": parents_dict[parent]["name"],
                        "parent_candidates": [
                            {"name": str(p), "type": type(p).__name__}
                            for p in parent_candidates
                        ],
                        "type": type(node).__name__,
                        **_column_key_data(node, table_keys),
                    }
                }
            )
        nodes += [
            {
                "data": {
                    "id": attr["name"],
                    "type": attr["type"],
                    **_table_key_data(parent, table_keys),
                }
            }
            for parent, attr in parents_dict.items()
        ]
    else:
        nodes = [
            {"data": {"id": str(node), **_table_key_data(node, table_keys)}}
            for node in vertices
        ]
    edge_elements: list[dict[str, dict[str, Any]]] = [
        {"data": {"id": f"e{i}", "source": str(edge[0]), "target": str(edge[1])}}
        for i, edge in enumerate(edges)
    ]
    return nodes + edge_elements
