from sqllineage.utils.constant import LineageLevel

logger = logging.getLogger(__name__)


def lazy_method(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        self = args[0]
        if not self._evaluated:
            self._eval()
        return func(*args, **kwargs)

    return wrapper


def lazy_property(func):
    return property(lazy_method(func))


def _format_foreign_key(fk: ForeignKey) -> str:
    cols = ", ".join(fk.columns)
    fk_cols = fk.columns[0] if len(fk.columns) == 1 else f"({cols})"
    ref_cols = ", ".join(fk.referred_columns)
    return f"{fk_cols} -> {fk.referred_table}({ref_cols})"


def _format_table(table: Table | Path, table_keys: dict[Table, TableKeys]) -> str:
    if isinstance(table, Table) and (keys := table_keys.get(table)):
        parts = []
        if keys.primary_key:
            pk = ", ".join(keys.primary_key)
            parts.append(f"PK: {pk}")
        if keys.foreign_keys:
            fks = ", ".join(_format_foreign_key(fk) for fk in keys.foreign_keys)
            parts.append(f"FK: {fks}")
        summary = "; ".join(parts)
        return f"{table} [{summary}]"
    return str(table)


class LineageRunner:
    def __init__(
        self,
        sql: str,
        dialect: str = DEFAULT_DIALECT,
        metadata_provider: MetaDataProvider = DummyMetaDataProvider(),
        verbose: bool = False,
        silent_mode: bool = False,
        draw_options: dict[str, Any] | None = None,
        file_path: str = ".",
    ):
        """
        The entry point of SQLLineage after command line options are parsed.

        :param sql: a string representation of SQL statements.
        :param dialect: sql dialect
        :param metadata_provider: metadata service object providing table schema
        :param verbose: verbose flag indicating whether statement-wise lineage result will be shown
        :param silent_mode: boolean flag indicating whether to skip lineage analysis for unknown statement types
        :param file_path: path of the SQL file.
        """
        if dialect == SQLPARSE_DIALECT:
            warnings.warn(
                f"dialect `{SQLPARSE_DIALECT}` is deprecated, use `ansi` or dialect of your SQL instead. "
                f"`{SQLPARSE_DIALECT}` will be completely removed in v1.6.x",
                DeprecationWarning,
                stacklevel=2,
            )
        self._sql = sql
        self._file_path = file_path
        self._verbose = verbose
        self._draw_options = draw_options if draw_options else {}
        self._evaluated = False
        self._stmt: list[str] = []
        self._dialect = dialect
        self._metadata_provider = metadata_provider
        self._silent_mode = silent_mode
        self._table_keys: dict[Table, TableKeys] | None = None

    @lazy_method
    def __str__(self):
        """
        print out the Lineage Summary.
        """
        statements = self.statements()
        table_keys = self.get_table_keys()
        source_tables = "\n    ".join(
            _format_table(t, table_keys) for t in self.source_tables
        )
        target_tables = "\n    ".join(
            _format_table(t, table_keys) for t in self.target_tables
        )
        combined = f"""Statements(#): {len(statements)}
Source Tables:
    {source_tables}
Target Tables:
    {target_tables}
"""
        if self.intermediate_tables:
            intermediate_tables = "\n    ".join(
                _format_table(t, table_keys) for t in self.intermediate_tables
            )
            combined += f"""Intermediate Tables:
    {intermediate_tables}"""
        if self._verbose:
            result = ""
            for i, holder in enumerate(self._stmt_holders):
                stmt_short = statements[i].replace("\n", "")
                if len(stmt_short) > 50:
                    stmt_short = stmt_short[:50] + "..."
                content = str(holder).replace("\n", "\n    ")
                result += f"""Statement #{i + 1}: {stmt_short}
    {content}
"""
            combined = result + "==========\nSummary:\n" + combined
        return combined

    @lazy_method
    def to_cytoscape(self, level=LineageLevel.TABLE) -> list[dict[str, dict[str, Any]]]:
        """
        to turn the DAG into cytoscape format.
        """
        table_keys = self.get_table_keys()
        if level == LineageLevel.COLUMN:
            return to_cytoscape(
                self._sql_holder.column_lineage_graph,
                compound=True,
                table_keys=table_keys,
            )
        else:
            return to_cytoscape(
                self._sql_holder.table_lineage_graph,
                table_keys=table_keys,
            )

    def draw(self) -> None:
        """
        to draw the lineage directed graph
        """
        draw_options = self._draw_options
        if draw_options.get("f") is None:
            draw_options.pop("f", None)
            draw_options["e"] = self._sql
            draw_options["dialect"] = self._dialect
            draw_options["metadata_provider"] = self._metadata_provider
        return draw_lineage_graph(**draw_options)

    @lazy_method
    def statements(self) -> list[str]:
        """
        a list of SQL statements.
        """
        return self._stmt

    @lazy_property
    def source_tables(self) -> list[Table | Path]:
        """
        a list of source :class:`sqllineage.models.Table`
        """
        return sorted(self._sql_holder.source_tables, key=lambda x: str(x))

    @lazy_property
    def target_tables(self) -> list[Table | Path]:
        """
        a list of target :class:`sqllineage.models.Table`
        """
        return sorted(self._sql_holder.target_tables, key=lambda x: str(x))

    @lazy_property
    def intermediate_tables(self) -> list[Table | Path]:
        """
        a list of intermediate :class:`sqllineage.models.Table`
        """
        return sorted(self._sql_holder.intermediate_tables, key=lambda x: str(x))

    @lazy_method
    def get_table_keys(self) -> dict[Table, TableKeys]:
        """
        return primary key and foreign keys of tables in the lineage result.
        """
        if self._table_keys is None:
            self._table_keys = {}
            if self._metadata_provider:
                table_graph = self._sql_holder.table_lineage_graph
                vertices = table_graph.retrieve_vertices_by_props()
                tables = sorted(
                    {v for v in vertices if isinstance(v, Table)},
                    key=str,
                )
                for table in tables:
                   if keys := self._metadata_provider.get_table_keys(table):
                       self._table_keys[table] = keys
        return dict(self._table_keys)

    @lazy_method
    def find_nodes(
        self, predicate: Callable[[Column | Table | Path], bool]
    ) -> list[Column | Table | Path]:
        """
        a list of :class:`sqllineage.models.Column`/:class:`sqllineage.models.Table`/
        :class:`sqllineage.models.Path` for which ``predicate`` is true. To discover
        a ``node`` to pass into :meth:`get_column_lineage`, filter the result to
        :class:`sqllineage.models.Column` instances first.
        """
        return self._sql_holder.find_nodes(predicate)

    @lazy_method
    def get_column_lineage(
        self,
        exclude_path_ending_in_subquery=True,
        exclude_subquery_columns=False,
        node: Column | None = None,
    ) -> list[tuple[Column, ...]]:
        """
        a list of column tuple :class:`sqllineage.models.Column`

        :param exclude_path_ending_in_subquery:  exclude_subquery rename to exclude_path_ending_in_subquery
               exclude column from SubQuery in the ending path
        :param exclude_subquery_columns: exclude column from SubQuery in the path.
        :param node: restrict the result to paths that touch this column. Use
               :meth:`find_nodes` to discover a candidate, filtering its
               result to :class:`sqllineage.models.Column` instances first,
               since ``find_nodes`` can also return
               :class:`sqllineage.models.Table` and
               :class:`sqllineage.models.Path` vertices that this method
               rejects.
        """
        # sort by target column, then source column, then the full path as a
        # tiebreaker so paths sharing both endpoints get a deterministic order
        # regardless of Column's hash-randomization-dependent set iteration order
        return sorted(
            self._sql_holder.get_column_lineage(
                exclude_path_ending_in_subquery, exclude_subquery_columns, node
            ),
            key=lambda x: (str(x[-1]), str(x[0]), tuple(str(c) for c in x)),
        )

    def print_column_lineage(self, node: Column | None = None) -> None:
        """
        print column level lineage to stdout

        :param node: see :meth:`get_column_lineage`
        """
        for path in self.get_column_lineage(node=node):
            print(" <- ".join(str(col) for col in reversed(path)))

    def print_table_lineage(self) -> None:
        """
        print table level lineage to stdout
        """
        print(str(self))

    def _eval(self) -> None:
        analyzer = (
            SqlParseLineageAnalyzer(self._sql)
            if self._dialect == SQLPARSE_DIALECT
            else SqlFluffLineageAnalyzer(
                self._sql, self._file_path, self._dialect, self._silent_mode
            )
        )
        self._stmt = analyzer.statements
        with self._metadata_provider.session() as session:
            stmt_holders = []
            for stmt in self._stmt:
                stmt_holder = analyzer.analyze(stmt, session.metadata_provider)
                if write := stmt_holder.write:
                    tgt_table = next(iter(write))
                    if isinstance(tgt_table, Table) and (
                        tgt_columns := stmt_holder.get_table_columns(tgt_table)
                    ):
                        session.register_session_metadata(tgt_table, tgt_columns)
                stmt_holders.append(stmt_holder)
            self._stmt_holders = stmt_holders
            self._sql_holder = SQLLineageHolder.of(
                session.metadata_provider, *stmt_holders
            )
        self._evaluated = True

    @staticmethod
    def supported_dialects() -> dict[str, list[str]]:
        """
        an ordered dict (so we can make sure the default parser implementation comes first)
        with key, value as parser_name, dialect list respectively
        """
        dialects = OrderedDict(
            [
                (
                    SqlFluffLineageAnalyzer.PARSER_NAME,
                    SqlFluffLineageAnalyzer.SUPPORTED_DIALECTS,
                ),
                (
                    SqlParseLineageAnalyzer.PARSER_NAME,
                    SqlParseLineageAnalyzer.SUPPORTED_DIALECTS,
                ),
            ]
        )
        return dialects
