from abc import ABC, abstractmethod
from collections.abc import Mapping, Sequence
from typing import Any

from sqllineage.core.models import Column, Table, TableKeys
from sqllineage.utils.entities import EdgeTuple


def _table_key_data(
    node: Any, table_keys: Mapping[Table, TableKeys] | None
) -> dict[str, Any]:
    if table_keys and isinstance(node, Table) and (keys := table_keys.get(node)):
        return {
            "primary_key": list(keys.primary_key),
            "foreign_keys": [
                {
                    "columns": list(fk.columns),
                    "referred_table": str(fk.referred_table),
                    "referred_columns": list(fk.referred_columns),
                }
                for fk in keys.foreign_keys
            ],
        }
    return {}


def _column_key_data(
    node: Any, table_keys: Mapping[Table, TableKeys] | None
) -> dict[str, Any]:
    if (
        table_keys
        and isinstance(node, Column)
        and isinstance(node.parent, Table)
        and (keys := table_keys.get(node.parent))
    ):
        col_keys: list[str] = []
        if node.raw_name in keys.primary_key:
            col_keys.append("PK")
        if any(node.raw_name in fk.columns for fk in keys.foreign_keys):
            col_keys.append("FK")
        if col_keys:
            return {"keys": col_keys}
    return {}


class GraphOperator(ABC):
    """
    Base class used to operator the graph structure that holder leverages to store lineage information
    """

    @abstractmethod
    def add_vertex_if_not_exist(self, vertex: Any, **props) -> None:
        """
        when vertex already exists, props will be updated
        """
        raise NotImplementedError

    @abstractmethod
    def retrieve_vertices_by_props(self, **props) -> list[Any]:
        """
        when props is empty, return all vertices
        """
        raise NotImplementedError

    @abstractmethod
    def retrieve_source_vertices(self) -> list[Any]:
        """
        source vertices are defined as vertices with no incoming edges and at least one outgoing edge
        """
        raise NotImplementedError

    @abstractmethod
    def retrieve_target_vertices(self) -> list[Any]:
        """
        target vertices are defined as vertices with no outgoing edges and at least one incoming edge
        """
        raise NotImplementedError

    @abstractmethod
    def retrieve_selfloop_vertices(self) -> list[Any]:
        """
        self-loop vertices are defined as vertices with edges pointing to themselves
        """
        raise NotImplementedError

    @abstractmethod
    def update_vertices(self, *vertices: Any, **props) -> None:
        raise NotImplementedError

    @abstractmethod
    def drop_vertices(self, *vertices: Any) -> None:
        """
        drop vertices from the graph if exists
        """
        raise NotImplementedError

    @abstractmethod
    def add_edge_if_not_exist(
        self, src_vertex: Any, tgt_vertex: Any, label: str, **props
    ) -> None:
        """
        when source and target vertices do not exist, they will be added to the graph first.
        when edge already exists, invoking this method should not create duplicate edge.
        """
        raise NotImplementedError

    @abstractmethod
    def retrieve_edges_by_label(self, label: str) -> list[EdgeTuple]:
        raise NotImplementedError

    @abstractmethod
    def retrieve_edges_by_vertex(
        self, vertex: Any, direction: str, label: str | None = None
    ) -> list[EdgeTuple]:
        raise NotImplementedError

    @abstractmethod
    def drop_edge(self, src_vertex: Any, tgt_vertex: Any) -> None:
        raise NotImplementedError

    @abstractmethod
    def get_sub_graph(self, *vertices: Any) -> "GraphOperator":
        raise NotImplementedError

    @abstractmethod
    def ancestors(self, vertex: Any) -> set[Any]:
        """
        all vertices with a path leading to vertex, not just direct predecessors.

        Raises KeyError if vertex is not a vertex in the graph. Implementations
        must agree on this.
        """
        raise NotImplementedError

    @abstractmethod
    def descendants(self, vertex: Any) -> set[Any]:
        """
        all vertices with a path leading from vertex, not just direct successors.

        Raises KeyError if vertex is not a vertex in the graph. Implementations
        must agree on this.
        """
        raise NotImplementedError

    @abstractmethod
    def merge(self, other: "GraphOperator") -> None:
        """
        The vertices and edges from other graph will be added to current graph.
        When vertex or edge already exists, their props will be updated.
        In case of prop keys conflict, self takes precedence over other.
        """
        raise NotImplementedError

    @abstractmethod
    def list_lineage_paths(self, src_vertex: Any, tgt_vertex: Any) -> list[list[Any]]:
        """
        list all lineage paths (acyclic) in the graph from src_vertex to tgt_vertex.

        Raises KeyError if either src_vertex or tgt_vertex is not a vertex in
        the graph. Implementations must agree on this.

        When src_vertex == tgt_vertex, this returns [[src_vertex, src_vertex]] if
        a self-loop edge exists on that vertex, or [] otherwise. Implementations
        must agree on this: networkx's all_simple_paths trivially returns
        [[v]] for src == tgt regardless of whether an edge exists, while
        rustworkx's all_simple_paths only returns a (2-element) path when a
        real self-loop edge is present, see Qiskit/rustworkx#1617. This
        interface follows rustworkx's edge-presence semantics.
        """
        raise NotImplementedError

    @abstractmethod
    def to_cytoscape(
        self,
        compound: bool = False,
        table_keys: Mapping[Table, TableKeys] | None = None,
    ) -> list[dict[str, dict[str, Any]]]:
        """
        Convert graph to cytoscape format to be used in visualization.

        compound nodes is used to group nodes together to their parent.
        See https://js.cytoscape.org/#notation/compound-nodes for reference.
        """
        raise NotImplementedError

    @staticmethod
    def _build_cytoscape(
        vertices: Sequence[Any],
        edges: Sequence[tuple[Any, Any]],
        compound: bool = False,
        table_keys: Mapping[Table, TableKeys] | None = None,
    ) -> list[dict[str, dict[str, Any]]]:
        nodes: list[dict[str, dict[str, Any]]]
        if compound:
            parents_dict: dict[Any, dict[str, str]] = {}
            for node in vertices:
                parent = getattr(node, "parent", None)
                parents_dict[parent] = {
                    "name": str(parent) if parent is not None else "<unknown>",
                    "type": (
                        type(parent).__name__
                        if parent is not None
                        else "Table or SubQuery"
                    ),
                }
            nodes = []
            for node in vertices:
                parent = getattr(node, "parent", None)
                parent_candidates = getattr(node, "parent_candidates", [])
                nodes.append(
                    {
                        "data": {
                            "id": str(node),
                            "parent": parents_dict[parent]["name"],
                            "parent_candidates": [
                                {"name": str(p), "type": type(p).__name__}
                                for p in parent_candidates
                            ],
                            "type": type(node).__name__,
                            **_column_key_data(node, table_keys),
                        }
                    }
                )
            nodes += [
                {
                    "data": {
                        "id": attr["name"],
                        "type": attr["type"],
                        **_table_key_data(parent, table_keys),
                    }
                }
                for parent, attr in parents_dict.items()
            ]
        else:
            nodes = [
                {"data": {"id": str(node), **_table_key_data(node, table_keys)}}
                for node in vertices
            ]
        edge_elements: list[dict[str, dict[str, Any]]] = [
            {"data": {"id": f"e{i}", "source": str(edge[0]), "target": str(edge[1])}}
            for i, edge in enumerate(edges)
        ]
        return nodes + edge_elements
