import ast
import builtins
import subprocess

changed_py = subprocess.check_output(["git", "diff", "--name-only"]).decode().splitlines()
changed_py = [f for f in changed_py if f.endswith(".py")]
print("Changed Python files:", changed_py)

builtin_names = set(dir(builtins)) - {"__name__", "__doc__", "__package__", "__loader__", "__spec__", "__build_class__", "__import__", "__debug__"}

for fname in changed_py:
    with open(fname) as f:
        src = f.read()
    # 1. Valid Python 3.10 syntax
    tree = ast.parse(src, filename=fname, feature_version=(3, 10))

    # 2. Check trailing newline and no trailing whitespace
    assert src.endswith("\n") and not src.endswith("\n\n"), f"{fname}: bad EOF newline"
    for lineno, line in enumerate(src.splitlines(), 1):
        assert line == line.rstrip(" \t"), f"{fname}:{lineno}: trailing whitespace"
        if len(line) > 120:
            print(f"ERROR >120: {fname}:{lineno} ({len(line)}): {line}")
        elif len(line) > 88:
            print(f"INFO >88: {fname}:{lineno} ({len(line)}): {line}")

    # 3. Check builtin shadowing (A001, A002, A003)
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            for arg in node.args.args + node.args.kwonlyargs:
                if arg.arg in builtin_names:
                    print(f"BUILTIN ARG SHADOW {fname}:{node.lineno}: {arg.arg}")
        elif isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
            if node.id in builtin_names:
                print(f"BUILTIN VAR SHADOW {fname}:{node.lineno}: {node.id}")

    # 4. Check unused imports
    imported = {}
    for node in tree.body:
        if isinstance(node, ast.Import):
            for alias in node.names:
                name = alias.asname or alias.name.split(".")[0]
                imported[name] = node.lineno
        elif isinstance(node, ast.ImportFrom):
            for alias in node.names:
                name = alias.asname or alias.name
                imported[name] = node.lineno
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load)}
    for name, lineno in imported.items():
        if name not in used:
            print(f"UNUSED IMPORT {fname}:{lineno}: {name}")

print("Static check complete!")
'

