import ast
import io
import subprocess
import tokenize

changed_py = subprocess.check_output(["git", "diff", "--name-only"]).decode().splitlines()
changed_py = [f for f in changed_py if f.endswith(".py")]

for fname in changed_py:
    with open(fname) as f:
        src = f.read()
    lines = src.splitlines()
    tokens = list(tokenize.generate_tokens(io.StringIO(src).readline))

    # Check matching brackets that span multiple lines
    stack = []
    for idx, tok in enumerate(tokens):
        if tok.type == tokenize.OP and tok.string in "([{":
            stack.append((idx, tok))
        elif tok.type == tokenize.OP and tok.string in ")]}":
            open_idx, open_tok = stack.pop()
            if open_tok.start[0] != tok.start[0]:
                # Multi-line bracketed group!
                # Find last meaningful token before close
                j = idx - 1
                while j > open_idx and tokens[j].type in (tokenize.NL, tokenize.NEWLINE, tokenize.COMMENT, tokenize.DEDENT, tokenize.INDENT):
                    j -= 1
                has_trailing_comma = tokens[j].type == tokenize.OP and tokens[j].string == ","
                # Reconstruct collapsed single-line approximation of lines from open_tok line to tok line
                span_lines = lines[open_tok.start[0]-1 : tok.end[0]]
                collapsed = span_lines[0].rstrip()
                for sl in span_lines[1:]:
                    collapsed += " " + sl.strip()
                # Clean spaces just inside brackets
                for o, c in [("(", ")"), ("[", "]"), ("{", "}")]:
                    collapsed = collapsed.replace(o + " ", o).replace(" " + c, c)
                collapsed = collapsed.replace(",)", ")").replace(",]", "]").replace(",}", "}")
                if not has_trailing_comma and len(collapsed) <= 88 and "\"\"\"" not in collapsed:
                    print(f"POTENTIAL BLACK COLLAPSE {fname}:{open_tok.start[0]}-{tok.end[0]} (len={len(collapsed)}): {collapsed}")

    # Check mypy disallow_any_generics in sqllineage/
    if fname.startswith("sqllineage/"):
        tree = ast.parse(src, filename=fname)
        bare_generics = {"dict", "list", "tuple", "set", "frozenset", "Mapping", "Sequence", "Callable", "Iterable"}
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                for ann in [a.annotation for a in node.args.args + node.args.kwonlyargs] + [node.returns]:
                    if isinstance(ann, ast.Name) and ann.id in bare_generics:
                        print(f"BARE GENERIC {fname}:{ann.lineno}: {ann.id}")
            elif isinstance(node, ast.AnnAssign):
                if isinstance(node.annotation, ast.Name) and node.annotation.id in bare_generics:
                    print(f"BARE GENERIC {fname}:{node.lineno}: {node.annotation.id}")

print("Deep audit finished!")
'

